                retention_amount = employee_id.retention_amount
                ing_001_cat = payslip.env.ref('basic_rule.hr_salary_rule_category_ing_001')
                ina_001_cat = payslip.env.ref('basic_rule.hr_salary_rule_category_ina_001')
                inn_001_cat = payslip.env.ref('basic_rule.hr_salary_rule_category_inn_001')
                da_001_cat = payslip.env.ref('basic_rule.hr_salary_rule_category_da_001')
                net_cat =  payslip.env.ref('basic_rule.hr_salary_rule_net')

                cat_dict = categories
                if employee_id.retention_on =='total_income':
                    result += cat_dict[ing_001_cat.code]
                elif  employee_id.retention_on =='affection_income':
                    result += cat_dict[ina_001_cat.code]
                elif  employee_id.retention_on =='unaffected_income':
                    result  += cat_dict[inn_001_cat.code]
                elif employee_id.retention_on =='net_income':
                    ina_001_amount = cat_dict['INA_001'] if "INA_001" in cat_dict.keys() and cat_dict['INA_001'] else 0
                    da_001_amount = cat_dict['DA_001'] if "DA_001" in cat_dict.keys() and cat_dict['DA_001'] else 0
                    result += ina_001_amount - da_001_amount
                elif employee_id.retention_on =='net_payable':
                    if inputs.get('NET') and inputs.get('NET').amount > 0:
                        result = inputs['NET'].amount
                    else:
                        cat_ing_001 = cat_dict['ING_001'] if cat_dict.get('ING_001') else 0
                        cat_ing_ded = cat_dict['DED'] if cat_dict.get('DED') else 0
                        result = cat_ing_001 - cat_ing_ded
                else:
                    result = 0
                result *= employee_id.judicial_discount_percent or 0.0
                if retention_amount > 0 and result > retention_amount:
                    result = retention_amount
            else:
                result = 0
        else:
            result = 0

