            if employee_id:
                total = 0.0
                global_data = globals()
                for parents in parents_id:
                    if parents.relation_id.id == payslip.env.ref('personal_information.relation_child').id and parents.age > parents.max_age:
                        total = total + 0
                    else:
                        if parents.percentage_eps > 0:
                            parent_amount = (parents.percentage_eps/100)*global_data['ESA_100']
                            total = total + parent_amount
                        if parents.tax_eps > 0:
                            total = total + parents.tax_eps
                result = total
            else:
                result = 0

